class Jacket < Formula
  desc "Independent toolchain for the Jai language: compiler, LSP, linter and formatter"
  homepage "https://github.com/matteopolak/jacket"
  # Plus the jaic Runtime Library Exception (LICENSE-EXCEPTION), which has no SPDX identifier; the
  # bundled stdlib is also available under MIT OR Apache-2.0 (stdlib/LICENSE.md).
  license "AGPL-3.0-or-later"

  livecheck do
    url :stable
    strategy :github_latest
  end

  on_macos do
    on_arm do
      url "https://github.com/matteopolak/jacket/releases/download/v0.40.0/jacket-macos-arm64.tar.gz"
      sha256 "b0bc27545a0af4e4a4e2c86588a897f7422ce334038d45002b1091b1bc055ef2"
    end
    on_intel do
      url "https://github.com/matteopolak/jacket/releases/download/v0.40.0/jacket-macos-x64.tar.gz"
      sha256 "9e6a42d0e5b5cef94b6ee44ba75c586f8572b298fd2d5f35972d95d427b8388b"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/matteopolak/jacket/releases/download/v0.40.0/jacket-linux-arm64.tar.gz"
      sha256 "70b0ae1bc32d74c70e79c8ebd45ee971195db272383474d4315a32203b80ea29"
    end
    on_intel do
      url "https://github.com/matteopolak/jacket/releases/download/v0.40.0/jacket-linux-x64.tar.gz"
      sha256 "7d0d43bd83bae225360da346b93524fda664131b88607c467ca991f45ef08bdc"
    end
  end

  def install
    # jacket starts the other tools from beside the real file behind its bin/ symlink.
    # jaic, jailint and jailsp find stdlib/ (including its prelude) next to the real file
    # behind the bin/ symlinks, and native libraries (wgpu-native, stb_*, rpmalloc) in
    # ../native-libs. jaic opens its code generation library (libjaic_backend) from beside the
    # real file too, on the first build that writes native code.
    libexec.install "jacket", "jaic", "jailsp", "jailint", "jaifmt", "stdlib"
    libexec.install Dir["libjaic_backend.*"]
    libexec.install "native-libs"
    bin.install_symlink libexec/"jacket", libexec/"jaic", libexec/"jailsp", libexec/"jailint", libexec/"jaifmt"
    doc.install "README.md", "CHANGELOG.md"
  end

  test do
    (testpath/"hello.jai").write <<~JAI
      #import "Basic";

      main :: () {
          print("Hello from Homebrew!\\n");
      }
    JAI
    assert_equal "Hello from Homebrew!\n", shell_output("#{bin}/jaic hello.jai -interp")
    assert_equal "main :: () {\n    x := 1;\n}\n", pipe_output("#{bin}/jaifmt --stdin", "main::(){x:=1;}")
    system bin/"jailint", "hello.jai"
    assert_match "jacket", shell_output("#{bin}/jacket version")
  end
end
